import{c as e,Q as l,j as d,m as a}from"./chunks/framework.Br9POBWI.js";const h=JSON.parse('{"title":"公式使用指南 (Formula Usage)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/point/formula.md","filePath":"guide/point/formula.md","lastUpdated":1771156457000}'),o={name:"guide/point/formula.md"};function i(c,t,r,n,s,x){return l(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="公式使用指南-formula-usage" tabindex="-1">公式使用指南 (Formula Usage) <a class="header-anchor" href="#公式使用指南-formula-usage" aria-label="Permalink to &quot;公式使用指南 (Formula Usage)&quot;">​</a></h1><p>EMS Simulate 支持使用自定义公式对原始寄存器数据进行处理，将其转换为具有物理意义的工程值（如电压、电流、温度等）。</p><h2 id="_1-公式语法" tabindex="-1">1. 公式语法 <a class="header-anchor" href="#_1-公式语法" aria-label="Permalink to &quot;1. 公式语法&quot;">​</a></h2><p>公式基于 Python 表达式语法，支持基本的算术运算和内置函数。</p><ul><li>变量 <code>x</code> 代表寄存器读取到的<strong>原始值</strong>。</li></ul><h3 id="基本运算" tabindex="-1">基本运算 <a class="header-anchor" href="#基本运算" aria-label="Permalink to &quot;基本运算&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">运算符</th><th style="text-align:left;">说明</th><th style="text-align:left;">示例</th></tr></thead><tbody><tr><td style="text-align:left;"><code>+</code></td><td style="text-align:left;">加法</td><td style="text-align:left;"><code>x + 10</code></td></tr><tr><td style="text-align:left;"><code>-</code></td><td style="text-align:left;">减法</td><td style="text-align:left;"><code>x - 5</code></td></tr><tr><td style="text-align:left;"><code>*</code></td><td style="text-align:left;">乘法</td><td style="text-align:left;"><code>x * 0.1</code></td></tr><tr><td style="text-align:left;"><code>/</code></td><td style="text-align:left;">除法</td><td style="text-align:left;"><code>x / 100</code></td></tr><tr><td style="text-align:left;"><code>**</code></td><td style="text-align:left;">幂运算</td><td style="text-align:left;"><code>x ** 2</code> (平方)</td></tr><tr><td style="text-align:left;"><code>%</code></td><td style="text-align:left;">取模</td><td style="text-align:left;"><code>x % 10</code></td></tr></tbody></table><h2 id="_2-内置函数" tabindex="-1">2. 内置函数 <a class="header-anchor" href="#_2-内置函数" aria-label="Permalink to &quot;2. 内置函数&quot;">​</a></h2><p>支持使用 Python <code>math</code> 库中的常用函数。</p><table tabindex="0"><thead><tr><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th><th style="text-align:left;">示例</th></tr></thead><tbody><tr><td style="text-align:left;"><code>abs(x)</code></td><td style="text-align:left;">绝对值</td><td style="text-align:left;"><code>abs(x)</code></td></tr><tr><td style="text-align:left;"><code>round(x, n)</code></td><td style="text-align:left;">四舍五入</td><td style="text-align:left;"><code>round(x * 0.1, 2)</code> (保留2位小数)</td></tr><tr><td style="text-align:left;"><code>math.sin(x)</code></td><td style="text-align:left;">正弦</td><td style="text-align:left;"><code>math.sin(x)</code></td></tr><tr><td style="text-align:left;"><code>math.cos(x)</code></td><td style="text-align:left;">余弦</td><td style="text-align:left;"><code>math.cos(x)</code></td></tr><tr><td style="text-align:left;"><code>math.sqrt(x)</code></td><td style="text-align:left;">平方根</td><td style="text-align:left;"><code>math.sqrt(x)</code></td></tr><tr><td style="text-align:left;"><code>max(x, y)</code></td><td style="text-align:left;">取最大值</td><td style="text-align:left;"><code>max(x, 0)</code></td></tr><tr><td style="text-align:left;"><code>min(x, y)</code></td><td style="text-align:left;">取最小值</td><td style="text-align:left;"><code>min(x, 100)</code></td></tr></tbody></table><h3 id="逻辑运算-若是支持" tabindex="-1">逻辑运算 (若是支持) <a class="header-anchor" href="#逻辑运算-若是支持" aria-label="Permalink to &quot;逻辑运算 (若是支持)&quot;">​</a></h3><p>支持简单的条件表达式（三元运算符）： <code>value_if_true if condition else value_if_false</code></p><ul><li>示例：<code>x / 10 if x &gt; 0 else 0</code></li></ul><h2 id="_3-典型应用场景" tabindex="-1">3. 典型应用场景 <a class="header-anchor" href="#_3-典型应用场景" aria-label="Permalink to &quot;3. 典型应用场景&quot;">​</a></h2><h3 id="_3-1-精度转换" tabindex="-1">3.1 精度转换 <a class="header-anchor" href="#_3-1-精度转换" aria-label="Permalink to &quot;3.1 精度转换&quot;">​</a></h3><p>将整数寄存器值转换为浮点数：</p><ul><li>寄存器值 <code>1234</code>，实际值 <code>12.34</code></li><li>公式：<code>x * 0.01</code> 或 <code>x / 100</code></li></ul><h3 id="_3-2-单位转换" tabindex="-1">3.2 单位转换 <a class="header-anchor" href="#_3-2-单位转换" aria-label="Permalink to &quot;3.2 单位转换&quot;">​</a></h3><ul><li>摄氏度转华氏度：<code>x * 1.8 + 32</code></li><li>分钟转秒：<code>x * 60</code></li></ul><h3 id="_3-3-位操作" tabindex="-1">3.3 位操作 <a class="header-anchor" href="#_3-3-位操作" aria-label="Permalink to &quot;3.3 位操作&quot;">​</a></h3><p>提取特定的位（Bit）：</p><ul><li>提取第 0 位：<code>(x &gt;&gt; 0) &amp; 1</code></li><li>提取第 3 位：<code>(x &gt;&gt; 3) &amp; 1</code></li></ul>',22)])])}const g=e(o,[["render",i]]);export{h as __pageData,g as default};
